head.script:
scwin.userId     =   $c.session.getUserInfo("integUsrId");

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — search, init 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        let data = sessionStorage.getItem("searchCondition"); // 상세페이지 갔다 오면 검색조건 불러오기

        if(data) {
            const condition = JSON.parse(data);
            ibx_comNm.setValue(condition.searchIbxComNm);
            sbx_cmitPerfmYn.setValue(condition.searchsbxCmitPerfmYn);
            scwin.search();
        }

        await scwin.init();

    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDFIL52800.onpageload" });
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_search_onclick
 * @description 「조회」 버튼 클릭 — 확약사항 목록을 조회한다.
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_search_onclick = function (e) {
    try {
        scwin.search(true);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDFIL52800.btn_search_onclick" });
    }
};

/**
 * @method
 * @name sel_size_onviewchange
 * @description 페이지 사이즈 변경
 * @param {Object} info 이벤트 정보 객체
 * @returns {void}
 * @hidden N
 */
scwin.sel_size_onviewchange = function (info) {
    try {
        scwin.search(true);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDFIL52800.sel_size_onviewchange" });
    }
};

/**
 * @method
 * @name pageList1_onviewchange
 * @description 페이지네이션 현재 페이지 변경
 * @param {Object} info 이벤트 정보 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.pageList1_onviewchange = async function (info) {
    try {
        let currentPage = info.newSelectedIndex;
        dma_SearchReq.set("page", currentPage);
        await scwin.search(false);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDFIL52800.pageList1_onviewchange" });
    }
};

/**
 * @method
 * @name grd_Grid_oncellclick
 * @description 그리드 셀 클릭 — 선택 행의 상세 화면으로 이동한다.
 * @param {Number} rowIndex 행 인덱스
 * @param {Number} columnIndex 열 인덱스
 * @param {String} columnId 컬럼 id
 * @returns {void}
 * @hidden N
 */
scwin.grd_Grid_oncellclick = function (rowIndex, columnIndex, columnId) {
    try {
        if( columnId === "comAbbrv" ) {
            const moveUrl = "/ui/lst/lstinvstg/ULDFIL52810.xml";

            const param = {};
            param.BZ_PROCS_NO = dlt_CommitmentsRes.getCellData(rowIndex, "bzProcsNo");

            let condition = {
                searchIbxComNm: ibx_comNm.getValue(),
                searchsbxCmitPerfmYn: sbx_cmitPerfmYn.getValue()
            }

            sessionStorage.setItem("searchCondition", JSON.stringify(condition))

            $c.win.moveUrl(moveUrl, param);
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDFIL52800.grd_Grid_oncellclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name search
 * @description 확약사항 목록을 페이징 조회한다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function() {

    const options = {
        validateType : "alert", // alert|mark|all
        checkType : "single", // single|multi
        focus : true,
        fields : {
            ibx_comNm  : { required : true, name : "회사명" },
        }
    };

    if (!await $c.validate.validateDataCollect(grp_search, options)) {
        ibx_comNm.setValue("");
        sbx_cmitPerfmYn.setValue("a");
        dlt_CommitmentsRes.removeAll();
        return;
    }

    dma_SearchReq.set("comNm",  ibx_comNm.getValue()) // 회사명(필수)
    dma_SearchReq.set("cmitPerfmYn", sbx_cmitPerfmYn.getValue()) // 이행여부 (필수)
    dma_SearchReq.set("page", 1);// 현재페이지 초기화
    dma_SearchReq.set("userId", scwin.userId)

    dma_SearchReq.set("size", sbx_PerPage.getValue());// 페이지당 데이터 개수 (기본값: 10, 최대: 100)

    const sbmOptions = {
        id: "sbm_commitment",
        action: "/api/listing/listinvstg/commitments/select-list-paging",
        method: "get",
        ref: "dma_SearchReq",
        target: "dlt_CommitmentsRes=body.content",
        gridview: "grd_Grid",
        isProcessMsg : true
    };

    const res = await $c.sbm.executeDynamic(sbmOptions);

    if (res.responseJSON.success === true) {
        const resBody = res.responseJSON.body;
        pageList1.setSelectedIndex(resBody.page);
        tbx_totalCount.setValue(resBody.totalCount);
        txb_page.setValue(resBody.page);
        txb_totalPages.setValue(resBody.totalPages);

    }
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name scwin.init
 * @author yoo
 * @date 2026. 07. 30
 * @description 초기화
 * @hidden N
 * @returns {void}
 */
scwin.init = async function () {

    // 조회조건 영역 엔터키 치면 자동 조회되도록 SET
    $c.win.setEnterKeyEvent(grp_search, scwin.btn_search_onclick);

    tbx_totalCount.setValue(0);
    pageList1.setCount("1");

    txb_page.setValue("0")
    txb_totalPages.setValue("0");

};
